public class ByteArrayOutputStream {
    private byte[] buffer;
    private int count;

    public ByteArrayOutputStream() {
        this.buffer = new byte[16];
    }

    public void write(final byte b[], final int off, final int len) throws IOException {
        if (b == null) {
            throw new NullPointerException("The byte array cannot be null");
        }
        if (off < 0 || len < 0 || off + len > b.length) {
            throw new IndexOutOfBoundsException("Invalid offset or length");
        }
        if (count + len > buffer.length) {
            expandBuffer(count + len);
        }
        System.arraycopy(b, off, buffer, count, len);
        count += len;
    }

    private void expandBuffer(int newCapacity) {
        int newLength = Math.max(buffer.length << 1, newCapacity);
        byte[] newBuffer = new byte[newLength];
        System.arraycopy(buffer, 0, newBuffer, 0, count);
        buffer = newBuffer;
    }

    // Additional methods like close, reset, toByteArray, etc. can be added here
}

