public class LogarithmCalculator {

    /**
     * Computes floor(log2(n)) + 1
     */
    private int computeBinaryLog(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("Input must be a positive integer.");
        }
        return 31 - Integer.numberOfLeadingZeros(n);
    }

    public static void main(String[] args) {
        LogarithmCalculator calculator = new LogarithmCalculator();
        System.out.println(calculator.computeBinaryLog(16)); // Output: 5
        System.out.println(calculator.computeBinaryLog(10)); // Output: 4
